WITH windows AS (SELECT 0 AS sample, 25900 AS pid, 15936130000000 AS start_ns, 15938480956791 AS end_ns UNION ALL SELECT 1 AS sample, 25900 AS pid, 15939450000000 AS start_ns, 15941774021208 AS end_ns UNION ALL SELECT 2 AS sample, 25900 AS pid, 15942630000000 AS start_ns, 15945015139375 AS end_ns UNION ALL SELECT 3 AS sample, 25900 AS pid, 15945930000000 AS start_ns, 15948195058291 AS end_ns UNION ALL SELECT 4 AS sample, 25900 AS pid, 15949370000000 AS start_ns, 15951633670708 AS end_ns UNION ALL SELECT 5 AS sample, 25900 AS pid, 15952590000000 AS start_ns, 15954910142458 AS end_ns UNION ALL SELECT 6 AS sample, 25900 AS pid, 15955730000000 AS start_ns, 15958078570666 AS end_ns UNION ALL SELECT 7 AS sample, 25900 AS pid, 15959050000000 AS start_ns, 15961374392583 AS end_ns UNION ALL SELECT 8 AS sample, 25900 AS pid, 15962220000000 AS start_ns, 15964492876584 AS end_ns UNION ALL SELECT 9 AS sample, 25900 AS pid, 15965470000000 AS start_ns, 15967719239874 AS end_ns UNION ALL SELECT 10 AS sample, 25900 AS pid, 15968590000000 AS start_ns, 15970881040999 AS end_ns UNION ALL SELECT 11 AS sample, 25900 AS pid, 15971910000000 AS start_ns, 15974183689375 AS end_ns UNION ALL SELECT 12 AS sample, 25900 AS pid, 15974950000000 AS start_ns, 15977216162042 AS end_ns UNION ALL SELECT 13 AS sample, 25900 AS pid, 15978220000000 AS start_ns, 15980477524875 AS end_ns UNION ALL SELECT 14 AS sample, 25900 AS pid, 15981780000000 AS start_ns, 15984043481624 AS end_ns UNION ALL SELECT 15 AS sample, 25900 AS pid, 15985190000000 AS start_ns, 15987449209124 AS end_ns UNION ALL SELECT 16 AS sample, 25900 AS pid, 15988400000000 AS start_ns, 15990678688291 AS end_ns UNION ALL SELECT 17 AS sample, 25900 AS pid, 15991630000000 AS start_ns, 15993921240416 AS end_ns UNION ALL SELECT 18 AS sample, 25900 AS pid, 15994770000000 AS start_ns, 15997055979582 AS end_ns UNION ALL SELECT 19 AS sample, 25900 AS pid, 15998000000000 AS start_ns, 16000260303458 AS end_ns UNION ALL SELECT 20 AS sample, 25900 AS pid, 16001050000000 AS start_ns, 16003305809250 AS end_ns UNION ALL SELECT 21 AS sample, 25900 AS pid, 16004540000000 AS start_ns, 16006816230707 AS end_ns)
SELECT w.sample, count(*) AS app_frame_records,
 sum(CASE WHEN a.jank_type LIKE '%App Deadline Missed%' THEN 1 ELSE 0 END) AS app_deadline_misses,
 sum(CASE WHEN a.jank_type != 'None' THEN 1 ELSE 0 END) AS all_jank_records,
 sum(CASE WHEN a.present_type = 'Dropped Frame' THEN 1 ELSE 0 END) AS dropped_frame_records,
 round(avg(a.dur)/1e6,2) AS mean_actual_frame_ms,
 round(max(a.dur)/1e6,2) AS max_actual_frame_ms,
 group_concat(a.dur) AS actual_durations_ns
FROM windows w JOIN process p ON p.pid=w.pid
JOIN actual_frame_timeline_slice a ON a.upid=p.upid
WHERE a.ts >= w.start_ns AND a.ts < w.end_ns AND a.dur > 0
GROUP BY w.sample ORDER BY w.sample